pub extern "C" fn spikard_app_trace(
    owner: AlefHandle,
    callback: extern "C" fn(*mut c_void, *const c_char) -> *mut c_char,
    response_free: extern "C" fn(*mut c_char),
    context: *mut c_void,
    path: *const c_char,
) -> i32 {
    catch_ffi_panic(1, || {
        if owner == 0 {
            return 1; // Error: null pointer
        }
        if path.is_null() {
            return 1; // Error: null pointer;
        }

        let path = if path.is_null() {
            String::new()
        } else {
            // SAFETY: caller guarantees a valid null-terminated C string.
            unsafe { CStr::from_ptr(path) }.to_string_lossy().into_owned()
        };

        let builder = spikard::RouteBuilder::new(spikard::Method::Trace, path);

        let bridge = FfiHandlerBridge {
            callback,
            response_free,
            context,
        };
        let handler: Arc<dyn spikard::Handler> = Arc::new(bridge);

        // SAFETY: owner was allocated by _new() and is valid until freed.
        match with_handle_mut::<AppOpaque, _>(owner, |service| {
            service
                .inner
                .as_mut()
                .map(|owner_ref| owner_ref.route(builder, handler).map(|_| ()))
        }) {
            Ok(Some(Ok(()))) => 0,
            Ok(Some(Err(error))) => {
                set_last_error(2, &error.to_string());
                1
            }
            Ok(None) => 1,
            Err(error) => {
                set_handle_error(&error);
                1
            }
        }
    })
}
/// Configure the service via 'config'.
///
/// # Safety
/// - `owner` must be a valid pointer returned by `spikard_app_new()` and not yet freed.
/// - The same `owner` pointer is returned on success — the caller does **not**
///   need to swap the handle they hold. Returns `null` on failure (the original
///   handle is still valid in that case but should be inspected for usability).
#[unsafe(no_mangle)]
pub extern "C" fn spikard_app_config(owner: AlefHandle, config: AlefHandle) -> AlefHandle {
    catch_ffi_panic(0, || {
        if owner == 0 {
            return 0;
        }

        let config = match with_handle::<spikard::ServerConfig, _>(config, Clone::clone) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };

        // SAFETY: owner was allocated by _new() and is valid until freed.
        // Take the inner box out, transform it, and put the result back. The opaque
        // shell stays at the same address so the caller's handle remains valid.
        match with_handle_mut::<AppOpaque, _>(owner, |service| {
            let inner = match service.inner.take() {
                Some(boxed) => *boxed,
                None => return false,
            };
            service.inner = Some(Box::new(inner.config(config)));
            true
        }) {
            Ok(true) => owner,
            Ok(false) => 0,
            Err(error) => {
                set_handle_error(&error);
                0
            }
        }
    })
}
/// Run the service entrypoint 'run'.
///
/// # Safety
/// - `owner` must be a valid pointer returned by `spikard_app_new()` and not yet freed.
/// - The inner owner value is moved out by this call and the opaque shell is left
///   with `inner = None`. The caller may still invoke `()`
///   afterwards to release the shell; subsequent registration/configurator calls
///   on the same pointer will fail with the null-return error code.
#[unsafe(no_mangle)]
pub extern "C" fn spikard_app_ep_run(owner: AlefHandle) -> i32 {
    catch_ffi_panic(1, || {
        if owner == 0 {
            return 1;
        }

        // SAFETY: owner was allocated by _new() and is valid until freed.
        // Move the inner owner out; leave `None` behind so the consumer's deferred
        // `_free` call drops the empty shell instead of touching a moved-from box.
        let service = match take_handle::<AppOpaque>(owner) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 1;
            }
        };
        let inner = match service.inner {
            Some(boxed) => *boxed,
            None => return 1,
        };
        // 16 MiB: tokio's ~2 MB default worker stack can overflow on a deep
        // extraction future (a nested archive member, a multi-stage OCR pipeline), and a
        // stack overflow aborts the process with SIGBUS instead of raising a catchable panic.
        const ENTRYPOINT_RUNTIME_STACK_SIZE_BYTES: usize = 16 * 1024 * 1024;
        let rt = tokio::runtime::Builder::new_multi_thread()
            .enable_all()
            .thread_stack_size(ENTRYPOINT_RUNTIME_STACK_SIZE_BYTES)
            .build()
            .expect("failed to create tokio runtime");
        match rt.block_on(inner.run()) {
            Ok(_) => 0,
            Err(error) => {
                set_last_error(2, &error.to_string());
                1
            }
        }
    })
}
/// Run the service entrypoint 'into_router'.
///
/// # Safety
/// - `owner` must be a valid pointer returned by `spikard_app_new()` and not yet freed.
/// - The inner owner value is moved out by this call and the opaque shell is left
///   with `inner = None`. The caller may still invoke `()`
///   afterwards to release the shell; subsequent registration/configurator calls
///   on the same pointer will fail with the null-return error code.
#[unsafe(no_mangle)]
pub extern "C" fn spikard_app_ep_into_router(owner: AlefHandle) -> i32 {
    catch_ffi_panic(1, || {
        if owner == 0 {
            return 1;
        }

        // SAFETY: owner was allocated by _new() and is valid until freed.
        // Move the inner owner out; leave `None` behind so the consumer's deferred
        // `_free` call drops the empty shell instead of touching a moved-from box.
        let service = match take_handle::<AppOpaque>(owner) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 1;
            }
        };
        let inner = match service.inner {
            Some(boxed) => *boxed,
            None => return 1,
        };
        match inner.into_router() {
            Ok(_) => 0,
            Err(error) => {
                set_last_error(2, &error.to_string());
                1
            }
        }
    })
}
